-- 当角色走进一个 volume 时, 会触发本功能
-- 此后角色会尽可能地沿着一条曲线, 自动完成一段路径的行走
-- 在这个过程中, 本功能会模仿 玩家的设备输入方式, 直接向 InputManager 写入一个 moveInput 值
    

---@class AutoWalk
---@field enterVolumeBH   Engine.Modules.LuaBehaviour -- AutoWalkEnterVolume
---@field splineComputer    Dreamteck.Splines.SplineComputer
---@field debugPoint_1      UnityEngine.Transform
local AutoWalk = Class('AutoWalk')



-- ========================================================

--- lua:
local cs_coroutine = require 'XLua.cs_coroutine' -- 协程
local Yielders = CS.Engine.Lib.Yielders -- 协程


local QuestUtils = import('Game.DreamSpace.Quest.QuestUtils')
---@type LuaParametersReader
local LuaParametersReader = import('Game.Utils.LuaParametersReader')

---@type DreamSpaceStates
local DreamSpaceStates = import('Game.DreamSpace.Tools.DreamSpaceStates')

local InputManager = import('Game.DreamSpace.CharacterController.InputManager')

local DreamSpaceLuaUtils = import('Game.DreamSpace.Tools.DreamSpaceLuaUtils')

---:
local Object = CS.UnityEngine.Object
local GameObject = CS.UnityEngine.GameObject
local Mathf = CS.UnityEngine.Mathf
local Canvas = CS.UnityEngine.Canvas
local Transform = CS.UnityEngine.Transform
local Button = CS.UnityEngine.UI.Button
local RectTransform = CS.UnityEngine.RectTransform
local Vector2 = CS.UnityEngine.Vector2
local Vector3 = CS.UnityEngine.Vector3
local Quaternion = CS.UnityEngine.Quaternion
local Color = CS.UnityEngine.Color
local Time = CS.UnityEngine.Time
local Text = CS.UnityEngine.UI.Text
local Image = CS.UnityEngine.UI.Image
local Animation = CS.UnityEngine.Animation
local Animator = CS.UnityEngine.Animator


--- funtoy:
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool
local LuaParameters = CS.Engine.Modules.LuaParameters
local GlobalsInDreamSpace = CS.DreamSpace.GlobalsInDreamSpace

--- 曲线工具
local SplineComputer = CS.Dreamteck.Splines.SplineComputer
local SplineSample = CS.Dreamteck.Splines.SplineSample
local EvaluateMode = CS.Dreamteck.Splines.SplineComputer.EvaluateMode
local Spline = CS.Dreamteck.Splines.Spline
local SplinePoint = CS.Dreamteck.Splines.SplinePoint


-- ========================================================

local canTriggerTag = "Player"

local enterDegree = 80.0
local enterDegreeCosVal = Mathf.Cos( Mathf.Deg2Rad * enterDegree )


-- ========================================================

function AutoWalk:__init()
    self.controller = nil

    self.isInit = false
end


function AutoWalk:__delete()
    self.co_0 = nil
    self.co_1 = nil
end


function AutoWalk:Start()
    KTool.SetActive(self.controller.gameObject, true)
    
    assert( self.splineComputer )
    assert( self.debugPoint_1 )

    -- 
    assert( self.enterVolumeBH )
    self.enterVolume = DreamSpaceLuaUtils.GetLuaScr(self.enterVolumeBH.gameObject, "Game.DreamSpace.AutoWalk.AutoWalkEnterVolume" )

    assert( self.enterVolume )
    self.enterVolume:Init( self )

    self.curveBeginDir = self:CalculateCurveBeginDir() -- Vector3
    --print( "curveBeginDir = " .. self.curveBeginDir:ToString() )


    self.curvePoint0InitPos = self.splineComputer:GetPoint(0).position -- Vector3
    self.enterColliderInitPos = self.enterVolume:GetColliderCenterPos() -- Vector3
    self.initVec_collider2curveBegin = self.curvePoint0InitPos - self.enterColliderInitPos

    --
    DreamSpaceLuaUtils.StopCoroutine( self.co_0 )
    self.co_0 = cs_coroutine.start(self.DelayInit, self)
end


---@return System.Collections.IEnumerator
function AutoWalk:DelayInit() 
    -- 先等待一帧, 等新场景中新的 SwitchablePlayer 实例被创建
    coroutine.yield(Yielders.EndOfFrame)

    -- ----- role ------:
    -- 只会查找 N 次, 还是找不到就放弃 hint 功能了;
    self.role = nil -- 它的 pos 就是角色的 pos, 它的 forwatd 方向就是角色的当前运动方向
    for i=0, DreamSpaceStates.DelayInitWaitFrames do 
        self.role = GlobalsInDreamSpace.FindComponent("vTargetFollow")
        if not isNull(self.role) then
            break
        end
        coroutine.yield(Yielders.EndOfFrame)
    end

    if isNull( self.role ) then
        assert( false, "始终没能找到 gamoebj: SwitchablePlayer/VTarget/Follow, 请查找原因" )
        return
    end

    self.isInit = true
end



function AutoWalk:OnDestroy()

    DreamSpaceLuaUtils.StopCoroutine(self.co_0)
    DreamSpaceLuaUtils.StopCoroutine(self.co_1)
    self.co_0 = nil
    self.co_1 = nil    
    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end

-- =========================================== Self ================================================ --



---@param othCollider_ UnityEngine.Collider
function AutoWalk:Enter( othCollider_ ) 

    if      self.isInit == false
        or  othCollider_.gameObject:CompareTag(canTriggerTag) == false 
    then 
        return
    end 
    print( "== 进入 autoWalk 流程 ==" )

    if Vector3.Dot(self.role.forward, self.curveBeginDir) < enterDegreeCosVal then 
        print( "进入角度不对" )
        return
    end 
    DreamSpaceLuaUtils.StopCoroutine(self.co_1)
    self.co_1 = cs_coroutine.start(self.WalkingUpdate, self, othCollider_) --   协程测试:
end



function AutoWalk:CalculateCurveBeginDir() 
    local sample0 = self.splineComputer:Evaluate( 0.01 )
    return sample0.forward
end



function AutoWalk:GetRolePos() 
    local pos = self.role.position + self.role.forward * 0.3
    return pos
end



-- 根据 role 是从哪个位置进入 enter collider 的, 移动 cuver point 0, 
function AutoWalk:AdjustCurvePoint0() 

    local rolePos = self:GetRolePos()
    local newPos =  rolePos + self.initVec_collider2curveBegin
    self.splineComputer:SetPoint(0, SplinePoint( newPos ) )
end



---@return System.Collections.IEnumerator
---@param othCollider_ UnityEngine.Collider
function AutoWalk:WalkingUpdate( othCollider_ ) 


    self:AdjustCurvePoint0()


    local splineLength = self.splineComputer:CalculateLength() -- float  曲线总长度


    -- 第 1 帧:
    InputManager.SetInputMode( DreamSpaceStates.InputMode.FromCode )

    local frame1Pos = self:GetRolePos()

    InputManager.SetMoveInputFromCode( self.role.forward )
    coroutine.yield(Yielders.EndOfFrame)

    -- 第 2 帧:
    local moveVecOneFrame = self:GetRolePos() - frame1Pos
    --print( "moveVecOneFrame mag = " .. moveVecOneFrame.magnitude )
    local moveDistanceOneFrame = moveVecOneFrame.magnitude * 1.3
    
    local tOneFrame = moveDistanceOneFrame / splineLength -- 一帧走的 t值;

    local t = 0.0
    while t < 1.0 do
        local rolePos = self:GetRolePos()
        local sample = SplineSample()
        sample = self.splineComputer:Project( rolePos, sample )

        t = sample.percent + tOneFrame * 3
        local sample0 = self.splineComputer:Evaluate( Mathf.Clamp01(t) )


        self.debugPoint_1.position = sample0.position

        ---- 
        local rolePos = self:GetRolePos()
        local val = sample0.position - rolePos
        val.y = 0 
        val = val.normalized

        InputManager.SetMoveInputFromCode( val )


        coroutine.yield(Yielders.EndOfFrame)
    end 



    -- 最后

    InputManager.SetInputMode( DreamSpaceStates.InputMode.FromDevice )
end





return AutoWalk

